import React, {Component} from 'react';

class MembersTableHeader extends Component {

    constructor(props) {
        super(props);
    }

    render() {
        const {headers} = this.props;
        return (
            <thead>
            <tr>
                <th>{headers.header1}</th>
                <th>{headers.header2}</th>
            </tr>
            </thead>
        );
    }
}

export default MembersTableHeader;
